def isValidRoman(s):
    n = len(s)
    i = 0
    cnt = 0
    while i < n and s[i] == 'M' and cnt < 3:
        i += 1
        cnt += 1
    for one, five, ten in (('C', 'D', 'M'), ('X', 'L', 'C'), ('I', 'V', 'X')):
        pair = s[i:i + 2]
        if pair == one + ten or pair == one + five:
            i += 2
        else:
            if i < n and s[i] == five:
                i += 1
            cnt = 0
            while i < n and s[i] == one and cnt < 3:
                i += 1
                cnt += 1
    return i == n
